const TOOL_SCHEMA = {
  type: 'object',
  properties: {
    a: { type: 'number' },
    b: { type: 'number' },
    operation: { type: 'string', enum: OPERATIONS },
  },
  required: ['a', 'b', 'operation'],
  additionalProperties: false,
};

export async function listTools() {
  return [
    {
      name: 'calculate',
      description: 'Perform a basic arithmetic operation on two numbers.',
      inputSchema: TOOL_SCHEMA,
    },
  ];
}

function isNumber(value) {
  return typeof value === 'number' && Number.isFinite(value);
}

function validateArgs(args) {
  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
    throw new Error('Invalid arguments: expected an object');
  }

  const keys = Object.keys(args);
  const known = new Set(['a', 'b', 'operation']);
  for (const key of keys) {
    if (!known.has(key)) {
      throw new Error(`Unexpected field: ${key}`);
    }
  }

  if (!('a' in args)) throw new Error('Missing required field: a');
  if (!('b' in args)) throw new Error('Missing required field: b');
  if (!('operation' in args)) throw new Error('Missing required field: operation');

  if (!isNumber(args.a)) throw new Error('Field a must be a finite number');
  if (!isNumber(args.b)) throw new Error('Field b must be a finite number');

  if (!OPERATIONS.includes(args.operation)) {
    throw new Error(`Unsupported operation: ${args.operation}`);
  }
}

export async function callTool(name, args) {
  if (name !== 'calculate') {
    throw new Error(`Unknown tool: ${name}`);
  }

  validateArgs(args || {});

  const { a, b, operation } = args;
  let result;
  switch (operation) {
    case 'add':
      result = a + b;
      break;
    case 'subtract':
      result = a - b;
      break;
    case 'multiply':
      result = a * b;
      break;
    case 'divide':
      if (b === 0) {
        throw new Error('Division by zero is not allowed');
      }
      result = a / b;
      break;
    default:
      throw new Error(`Unsupported operation: ${operation}`);
  }

  return {
    content: [{ type: 'text', text: String(result) }],
  };
}
