import { listTools, callTool } from './server.mjs';
import assert from 'node:assert/strict';

const cases = [
  // [label, fn, shouldThrow]
  ['subtract', async () => { const r = await callTool('calculate',{a:10,b:4,operation:'subtract'}); assert.equal(r.content[0].text,'6'); }, false],
  ['multiply', async () => { const r = await callTool('calculate',{a:3,b:7,operation:'multiply'}); assert.equal(r.content[0].text,'21'); }, false],
  ['divide', async () => { const r = await callTool('calculate',{a:20,b:5,operation:'divide'}); assert.equal(r.content[0].text,'4'); }, false],
  ['divide by zero', async () => callTool('calculate',{a:5,b:0,operation:'divide'}), true],
  ['missing field', async () => callTool('calculate',{a:1,operation:'add'}), true],
  ['extra field', async () => callTool('calculate',{a:1,b:2,operation:'add',c:3}), true],
  ['unsupported op', async () => callTool('calculate',{a:1,b:2,operation:'pow'}), true],
  ['unknown tool', async () => callTool('frob',{a:1,b:2,operation:'add'}), true],
  ['non-number a', async () => callTool('calculate',{a:'1',b:2,operation:'add'}), true],
];

let pass = 0;
for (const [label, fn, shouldThrow] of cases) {
  try {
    await fn();
    if (shouldThrow) { console.log('FAIL (no throw):', label); }
    else { console.log('ok:', label); pass++; }
  } catch (e) {
    if (shouldThrow) { console.log('ok (threw):', label, '->', e.message); pass++; }
    else { console.log('FAIL (unexpected throw):', label, '->', e.message); }
  }
}

// schema additionalProperties check
const [t] = await listTools();
assert.equal(t.inputSchema.additionalProperties, false);
console.log('ok: additionalProperties=false');
console.log('PASS:', pass, '/', cases.length);
""}

